style.css:
@-moz-document domain("pinterest.com") {
:root {
    --bg: #f7f7f8;
    --surface: #ffffff;
    --text: #1f2937;
    --accent: #ffb6c1;
    --border: #e5e7eb;
  }

  body {
    background-color: var(FFC2CC) !important;
    color: var(FFC2CC) !important;
  }

  /* Example: change cards */
  .gridItem, .GrowthUnauthPinImage {
    background-color: var(FFFFFF) !important;
    border-color: var(FFFFFF) !important;
  }

  /* Example: accent links/buttons */
  a, button {
    color: var(--accent) !important;
  }
}
